import {clone,canonical,digest,validateExperience,emptyRepository,commit,branch,merge,revert,diff,getCommit,history,query,validateRepository,contextPacket,runBenchmark,BENCH_MEMORY} from './core.mjs';
import {seedRepository} from './seeds.mjs';
import {dcePage} from './dce-page.mjs';
import {DCE_EVIDENCE} from './dce-evidence.mjs';
import {workPage} from './work-page.mjs';
import {WORK_EVIDENCE} from './work-evidence.mjs';
import {startPage,guidedRecord} from './start-page.mjs';
const $ = s=>document.querySelector(s);
const esc = s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const short = id=>String(id||'').replace('sha256:','').slice(0,9);
const pretty=x=>JSON.stringify(x,null,2);
const labels={success:'Éxito',failure:'Fallo',partial:'Parcial',incomplete:'Incompleta',active:'Activa',superseded:'Sustituida',quarantined:'Cuarentena',observation:'Observación',hypothesis:'Hipótesis',intuition:'Intuición',negative:'Lección de fallo',disputed:'En disputa',software:'Software',investigacion:'Investigación',seguridad:'Seguridad',contradiction:'Mismo ámbito, valores incompatibles',scope_mismatch:'Ámbitos distintos',temporal_drift:'Cambio de versión'};
const badge=(s,text)=>`<span class="badge ${esc(s)}">${esc(text||labels[s]||s)}</span>`;
const storageKey='dxp-atlas-v01';
let repo,selected,detailTab='experience',busy=false,report=null,presentation=false,compareA,compareB,dceCase=0,workTask=0,workTab='tasks',guideStep=0,guideRevision=null;
let filters={text:'',domain:'',outcome:''};
let sourceInitialError='';
let storageBaseline;
try{storageBaseline=localStorage.getItem(storageKey);}catch{}
try {const raw=localStorage.getItem(storageKey);if(raw){repo=JSON.parse(raw);await validateRepository(repo);}}catch(e){sourceInitialError='No se pudo cargar la copia local: '+e.message+' La copia original sigue en el almacenamiento del navegador.';repo=null;}
if(repo){
 const retired=new Set(['sha256:5e6085c6eea12e130c0ba0f6f458e25b3cc6796c9d0d3698d1801120fef1012f']);
 for(const c of repo.commits)if(c.parents.some(p=>retired.has(p)))retired.add(c.commitId);
 if(repo.commits.some(c=>retired.has(c.commitId))){const clean=clone(repo);clean.commits=clean.commits.filter(c=>!retired.has(c.commitId));clean.refs=Object.fromEntries(Object.entries(clean.refs).filter(([,id])=>!retired.has(id)));await validateRepository(clean);repo=clean;try{storageBaseline=pretty(repo);localStorage.setItem(storageKey,storageBaseline);}catch{}}
}
if(!repo)repo=await seedRepository();
selected=repo.commits[1]?.commitId||repo.commits[0]?.commitId;
compareA=repo.commits[1]?.commitId;compareB=repo.commits[2]?.commitId;
function notice(text) {$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(notice.timer);notice.timer=setTimeout(()=>$('#toast').style.display='none',5500);}
function save(next) {
  let current;try{current=localStorage.getItem(storageKey);}catch{}
  if(current!==storageBaseline)throw Error('Otra pestaña cambió el repositorio. Exporta esta copia y recarga antes de escribir.');
  repo=next;
  if(sourceInitialError){notice('Copia local original preservada. Exporta el nuevo repositorio para conservar este trabajo.');return;}
  try{const text=pretty(repo);localStorage.setItem(storageKey,text);storageBaseline=text;}catch(e){notice('La copia está en memoria. Exporta el JSON para conservarla: '+e.message);}
}
async function mutate(fn) {if(busy)return;busy=true;try{await fn();}catch(e){notice(e.message);}finally{busy=false;}}
function download(name,text,type='application/json') {const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
const heading=(n,t,p,actions='')=>`<div class="page-heading"><div><div class="eyebrow"><span class="dot"></span> ${esc(n)}</div><h1>${t}</h1><p>${p}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</div>`;
function heroGraph(){return `<div class="hero-figure" aria-label="Historia ilustrativa: una experiencia fallida da lugar a dos ramas válidas bajo ámbitos distintos y a un cambio de versión"><div class="fig-top"><span>EXPERIENCE / CONCURRENCY</span><span class="live">● HISTORIA CONSERVADA</span></div><svg viewBox="0 0 500 340" role="img" aria-label="Grafo de revisiones ilustrativas"><defs><marker id="ha" markerWidth="7" markerHeight="7" refX="5" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="none" stroke="#718467"/></marker></defs><g fill="none" stroke="#718467" stroke-width="1.5" marker-end="url(#ha)"><path d="M117 108C117 166 100 145 100 192"/><path d="M117 108C117 152 326 130 326 192"/><path d="M100 247C100 306 215 267 244 299"/></g><text x="13" y="25" fill="#9baa90" font-family="Consolas,monospace" font-size="10">01 / EL ERROR TAMBIÉN ES EXPERIENCIA</text><rect x="14" y="41" width="244" height="75" rx="6" fill="#30392b" stroke="#6a674c"/><circle cx="34" cy="61" r="4" fill="#dc9d79"/><text x="46" y="65" font-family="Consolas,monospace" font-size="10" fill="#dc9d79">FAILURE · 20 WORKERS</text><text x="30" y="93" font-family="Segoe UI,Arial" font-size="16" fill="#e5ecdc">La API devuelve 429.</text><text x="206" y="147" fill="#9baa90" font-family="Consolas,monospace" font-size="10">SCOPE ≠ REGLA UNIVERSAL</text><rect x="14" y="183" width="194" height="76" rx="6" fill="#d7f78d"/><text x="30" y="207" font-family="Consolas,monospace" font-size="10" fill="#435932">BASIC / V1</text><text x="30" y="235" font-family="Segoe UI,Arial" font-size="19" fill="#20251e">4 workers. Funciona.</text><rect x="271" y="183" width="211" height="76" rx="6" fill="#30392b" stroke="#596e4b"/><text x="289" y="207" font-family="Consolas,monospace" font-size="10" fill="#bdd99c">PRO / V1</text><text x="289" y="235" font-family="Segoe UI,Arial" font-size="19" fill="#e5ecdc">12 workers. También.</text><rect x="230" y="288" width="252" height="37" rx="5" fill="#30392b" stroke="#596e4b"/><text x="246" y="312" font-family="Consolas,monospace" font-size="11" fill="#d7f78d">V2 → REVALIDAR ANTES DE REUSAR</text></svg><div class="fig-bottom"><span>Ejemplo sintético · sin llamadas a modelos</span><a href="#compare">Explorar el diff ↗</a></div></div>`;}
function vision(){return `<div class="wrap"><div class="eyebrow"><span class="dot"></span> DOMAIN EXPERIENCE PROTOCOL / EDICIÓN 04</div><section class="hero"><div><h1>Conservar<br>el camino.<br><em>No solo la llegada.</em></h1><p>Una solución tiene historia. DXP convierte las decisiones, los errores y los cambios de estrategia en experiencias que otros agentes pueden examinar y reutilizar con contexto.</p><div class="actions"><a class="btn dark" href="#atlas">Entrar al atlas <span>↗</span></a><button class="btn" data-action="present">Presentar la idea <span>↗</span></button></div><p class="small-text"><a href="#dce"><b>DCE: qué es, su repositorio y la integración ejecutada ↗</b></a><br><a href="#diary"><b>Diario: DXP registra su propia construcción ↗</b></a></p><div class="caption">PROTOTIPO FUNCIONAL · DATOS LOCALES · HIPÓTESIS ABIERTAS</div></div>${heroGraph()}</section><div class="ribbon"><div><b>${repo.commits.length.toString().padStart(2,'0')}</b><span>Revisiones navegables</span></div><div><b>${Object.keys(repo.refs).length.toString().padStart(2,'0')}</b><span>Ramas preservadas</span></div><div><b>SHA–256</b><span>Integridad de contenido</span></div><div><b>Abierto</b><span>JSON + núcleo portable</span></div></div><div class="section-head"><div><div class="eyebrow">01 / EL OBJETO DE ESTUDIO</div><h2>Lo que una respuesta final deja fuera.</h2></div><p>La unidad de valor es una experiencia situada: una trayectoria observable, una conclusión y las condiciones que permiten interpretarla.</p></div><div class="triptych"><article><span class="num">01 / RESULTADO</span><h3>«Usé cuatro workers.»</h3><p>El artefacto persiste. La exploración que lo hizo posible puede desaparecer al terminar la sesión.</p></article><article><span class="num">02 / PROCEDIMIENTO</span><h3>«Limita la concurrencia.»</h3><p>Una receta comprime el camino. Si pierde el ámbito, un acierto local puede convertirse en una mala regla general.</p></article><article class="focus"><span class="num">03 / EXPERIENCIA</span><h3>«Probé veinte. Falló.<br>Cambié el supuesto.»</h3><p>DXP conserva la observación, las alternativas, la decisión declarada, el resultado y su evidencia. También la rama que no funcionó.</p></article></div><div class="quote-band"><div><div class="eyebrow">LA PREGUNTA DXP</div><p class="small-text muted" style="color:#a9b798">Una propuesta de investigación.<br>Un contrato para empezar a probarla.</p></div><blockquote>¿Puede un agente heredar la experiencia de otro sin heredar ciegamente sus conclusiones?</blockquote></div><div class="section-head"><div><div class="eyebrow">02 / DE IDEA A OBJETO</div><h2>Un laboratorio que puedes usar.</h2></div><p>Explora ejemplos, registra tu propia experiencia y llévala a otro entorno como un objeto versionado.</p></div><div class="triptych"><article><span class="num">ATLAS / HISTORIA</span><h3>Cada decisión conserva su contexto.</h3><p>Navega trazas, consulta la evidencia, abre una rama y registra una revisión. El historial permanece.</p><a href="#atlas" class="btn ghost small">Abrir repositorio ↗</a></article><article><span class="num">DIFF / DIVERGENCIA</span><h3>Dos valores pueden ser correctos.</h3><p>Compara ámbitos, procedimientos y lecciones por campos tipados. Integra conservando padres y desacuerdos.</p><a href="#compare" class="btn ghost small">Comparar ramas ↗</a></article><article><span class="num">LAB / FALSABILIDAD</span><h3>Haz visible el fallo de transferencia.</h3><p>Ejecuta políticas reproducibles ante cambios de versión y registros no confiables. Inspecciona cada tarea.</p><a href="#lab" class="btn ghost small">Ejecutar ilustración ↗</a></article></div><div class="section-head"><div><div class="eyebrow">03 / POSICIÓN HONESTA</div><h2>Las piezas existen. La contribución se prueba.</h2></div><p>Reflexion, ExpeL, AgentRR y W3C PROV son antecedentes. DXP propone reunir historia, ámbito, procedencia y transferencia bajo un contrato de experiencia.</p></div><div class="split"><div class="panel"><h3>Lo que ya puedes hacer aquí</h3><p>Registrar experiencias, generar commits direccionados por contenido, ramificar, comparar, integrar, revertir y exportar. Los mismos objetos funcionan en el navegador y en la CLI incluida.</p><a href="kit.zip" class="btn dark small" download>Descargar el proyecto completo ↗</a></div><div class="panel"><h3>Lo que aún hay que demostrar</h3><p>Mejora de agentes reales, transferencia entre modelos, resistencia a inyecciones y originalidad científica. El microbenchmark ilustra decisiones deterministas; no mide inteligencia ni valida esas hipótesis.</p><a href="#protocol" class="btn ghost small">Leer contrato y plan de evaluación ↗</a></div></div></div>`;}
function scopeGrid(s){return `<div class="scope-grid">${[['provider','Proveedor'],['plan','Plan'],['apiVersion','Versión'],['environment','Entorno']].map(([k,l])=>`<div><span>${l}</span><strong>${esc(s[k])}</strong></div>`).join('')}</div>`;}
function dag(commits){const depth=new Map(),positions=new Map(),layers=new Map();for(const c of commits){const d=c.parents.length?Math.max(...c.parents.map(p=>depth.get(p)??-1))+1:0;depth.set(c.commitId,d);if(!layers.has(d))layers.set(d,[]);layers.get(d).push(c);}const width=680,height=(Math.max(0,...depth.values())+1)*84+30;for(const [d,cs] of layers)cs.forEach((c,i)=>positions.set(c.commitId,{x:width*(i+1)/(cs.length+1),y:40+d*84}));return `<svg viewBox="0 0 ${width} ${height}" style="height:${Math.min(550,height)}px" role="img" aria-label="Grafo de parentesco real de los commits de esta experiencia"><g fill="none" stroke="#adbaa0" stroke-width="1.5">${commits.flatMap(c=>c.parents.map(p=>{const a=positions.get(p),b=positions.get(c.commitId);return a?`<path d="M${a.x} ${a.y+12} C${a.x} ${a.y+50},${b.x} ${b.y-40},${b.x} ${b.y-13}"/>`:'';})).join('')}</g>${commits.map(c=>{const p=positions.get(c.commitId);return `<g><circle cx="${p.x}" cy="${p.y}" r="11" fill="${c.commitId===selected?'#517440':'#d7f78d'}" stroke="#668057"/><text x="${p.x}" y="${p.y+29}" text-anchor="middle" font-family="Consolas,monospace" font-size="10" fill="#526447">${short(c.commitId)} / ${esc(c.operation)}</text></g>`;}).join('')}</svg>`;}
function commitList(){const cs=query(repo,filters).slice().reverse();return `<div class="list-top"><span>${cs.length} REVISIÓN${cs.length===1?'':'ES'}</span><span>MÁS RECIENTE ↓</span></div>${cs.length?cs.map(c=>`<button class="commit-card ${selected===c.commitId?'selected':''}" data-action="select" data-id="${c.commitId}"><span class="row">${badge(c.experience.outcome.status)}${badge(c.experience.demo?'demo':'active',c.experience.demo?'DEMO':'PROPIA')}</span><h3>${esc(c.experience.title)}</h3><small>${esc(labels[c.experience.domain]||c.experience.domain)} &nbsp; / &nbsp; ${short(c.commitId)}</small></button>`).join(''):'<div class="empty">Sin resultados.<br>Cambia los filtros.</div>'}`.replaceAll('RÉVISION','REVISIÓN').replaceAll('PLUS RÉCENT','MÁS RECIENTE').replaceAll('PROPIA','PROPIA').replaceAll('Aucun résultat','Sin resultados').replaceAll('Modifie les filtres','Cambia los filtros');}
function detail(){if(!selected)return `<div class="empty">Registra tu primera experiencia.</div>`;const c=getCommit(repo,selected),e=c.experience;return `<div class="row">${badge(e.outcome.status)}${badge(e.validity)}${badge(e.demo?'demo':'active',e.demo?'Ejemplo sintético':'Registro propio')}<span class="muted mono" style="font-size:10px;margin-left:auto">${short(c.commitId)}</span></div><h2>${esc(e.title)}</h2><p class="muted">${esc(e.goal)}</p><div class="meta-strip"><span>${esc(e.actor.agentId)}</span><span>RUNTIME: ${esc(e.actor.runtime)}</span><span>${esc(c.timestamp.slice(0,16).replace('T',' '))} UTC</span></div><div class="row"><button class="btn small dark" data-action="revise">Registrar revisión ↗</button><button class="btn small ghost" data-action="branch">Crear rama</button><button class="btn small ghost" data-action="export-one">Exportar</button><button class="btn small ghost" data-action="compare-selected">Comparar</button></div><div class="tabs" role="tablist">${[['experience','Experiencia'],['trace','Trayectoria'],['evidence','Evidencia'],['history','Historia'],['json','Objeto JSON']].map(([k,t])=>`<button role="tab" aria-selected="${detailTab===k}" class="${detailTab===k?'active':''}" data-action="detail-tab" data-tab="${k}">${t}</button>`).join('')}</div><div class="tab-content">${detailContent(c)}</div>`;}
function detailContent(c){const e=c.experience;if(detailTab==='experience')return `<div class="eyebrow">ÁMBITO DE APLICACIÓN</div>${scopeGrid(e.scope)}<h3>Lo que dejó esta experiencia</h3>${e.lessons.map(l=>`<article class="lesson">${badge(l.type)}<p>${esc(l.claim)}</p><small>${esc(l.subject)} / ${esc(l.predicate)} = ${esc(l.value)}</small>${canonical(l.scope)!==canonical(e.scope)?scopeGrid(l.scope):''}</article>`).join('')}<div class="note"><b>Resultado:</b> ${esc(e.outcome.summary)}<br><b>Restricciones:</b> ${e.constraints.map(esc).join(' · ')}</div>${e.demo?'<div class="note warning">Ejemplo construido para explicar DXP. Sus métricas y evidencias son sintéticas; no documenta una ejecución de un modelo ni un experimento con agentes reales.</div>':'<div class="note">Evidencia declarada por el autor. Registrar y generar un hash no valida la verdad de la conclusión.</div>'}`;
  if(detailTab==='trace')return `<div class="timeline">${e.trace.map(s=>`<section class="step"><h4>${String(s.step).padStart(2,'0')} / ${esc(s.selected)} ${s.pivot?badge('demo','CAMBIO DE ESTRATEGIA'):''}</h4><dl>${[['Observación',s.observation],['Alternativas',s.alternatives.join(' · ')],['Razón declarada',s.rationaleSummary],['Acción',s.action],['Resultado',s.result],['Incertidumbre',s.uncertainty],['Evidencia',s.evidenceRefs.join(', ')]].map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join('')}</dl></section>`).join('')}</div>`;
  if(detailTab==='evidence')return `<div class="note">La evidencia vive dentro de la revisión. Sus IDs son referencias locales; el hash del commit cubre también este contenido. El sistema no visita enlaces ni confirma su autenticidad.</div>${e.evidence.map(v=>`<article class="evidence"><div class="row"><b>${esc(v.label)}</b>${badge('demo',v.kind==='illustrative'?'Ilustrativa':v.kind==='observed'?'Observada, declarada':'Declarada')}</div><small class="mono muted">${esc(v.id)}</small><pre>${esc(v.content)}</pre></article>`).join('')}`;
  if(detailTab==='history'){const cs=repo.commits.filter(x=>x.experience.experienceId===e.experienceId);return `<div class="eyebrow">DAG DE REVISIONES / ${cs.length} COMMITS</div><div class="dag-panel">${dag(cs)}</div><div class="note">El grafo muestra todos los commits de esta experiencia, incluidas sus ramas. Una reversión crea una revisión nueva que conserva el estado anterior.</div>${cs.slice().reverse().map(x=>`<div class="history-row"><div><b>${esc(x.message)}</b><br><small>${short(x.commitId)} · ${esc(x.operation)} · ${esc(x.timestamp.slice(0,16))}</small><div class="row">${Object.entries(repo.refs).filter(([k,id])=>id===x.commitId).map(([k])=>badge('demo',k)).join('')}</div></div><button class="btn small ghost" data-action="select" data-id="${x.commitId}">Ver</button><button class="btn small ghost" data-action="revert" data-id="${x.commitId}">Revertir a este</button></div>`).join('')}`;}
  return `<div class="row"><button class="btn small ghost" data-action="copy-json">Copiar objeto</button><button class="btn small ghost" data-action="export-one">Descargar JSON</button></div><pre class="code">${esc(pretty(c))}</pre>`;
}
function atlas(){return `<div class="wrap">${heading('ATLAS / REPOSITORIO','La historia de una conclusión.','Experiencias, revisiones y ramas. Los registros propios se conservan en este navegador y se pueden transferir como JSON.',`<button class="btn ghost" data-action="import">Importar JSON ↙</button><button class="btn dark" data-action="export-all">Exportar repositorio ↗</button>`)}<div class="guide"><div><h3>Empieza por el fallo. Sigue la corrección.</h3><p>Abre «La intuición», recorre su trayectoria y compárala con las ramas Basic y Pro.</p></div><button class="btn small" data-action="tour">Ver el primer intento ↗</button></div><div class="toolbar"><input id="search" aria-label="Buscar experiencias" placeholder="Buscar un error, una decisión o una lección…" value="${esc(filters.text)}"><select id="filter-domain" aria-label="Filtrar dominio"><option value="">Todos los dominios</option>${[...new Set(repo.commits.map(c=>c.experience.domain))].map(d=>`<option value="${esc(d)}" ${filters.domain===d?'selected':''}>${esc(labels[d]||d)}</option>`).join('')}</select><select id="filter-outcome" aria-label="Filtrar resultado"><option value="">Todos los resultados</option>${['success','failure','partial','incomplete'].map(x=>`<option value="${x}" ${filters.outcome===x?'selected':''}>${labels[x]}</option>`).join('')}</select></div><div class="repo-layout"><aside class="repo-list" id="repo-results" aria-label="Revisiones">${commitList()}</aside><section class="detail" id="detail">${detail()}</section></div><div class="note">Almacenamiento local, sin sincronización entre dispositivos. Exportar el repositorio incluye los registros con clasificación «local»; revisa su contenido antes de compartirlo.</div></div>`;}
const options=id=>repo.commits.map(c=>`<option value="${c.commitId}" ${c.commitId===id?'selected':''}>${esc(c.experience.title)} · ${short(c.commitId)}</option>`).join('');
function compare(){if(!compareA||!compareB)return `<div class="wrap">${heading('DIFF','Faltan revisiones.','Registra al menos dos revisiones para comparar.')}</div>`;const a=getCommit(repo,compareA),b=getCommit(repo,compareB),d=diff(a,b);return `<div class="wrap">${heading('DIFF / CONFLICTOS','Comparar sin borrar la diferencia.','El diff contrasta campos y claves de lección. Detecta cambios de ámbito y valores distintos; no interpreta automáticamente el significado de texto libre.')}<div class="compare-selects"><select id="compare-a" aria-label="Revisión A">${options(compareA)}</select><span class="arrow">⇄</span><select id="compare-b" aria-label="Revisión B">${options(compareB)}</select></div><div class="actions"><button class="btn ghost small" data-action="swap">Intercambiar A y B</button><button class="btn dark small" data-action="merge" ${a.experience.experienceId!==b.experience.experienceId||a.commitId===b.commitId?'disabled':''}>Integrar conservando ambos padres ↗</button><button class="btn ghost small" data-action="export-diff">Exportar diff</button></div>${a.experience.experienceId!==b.experience.experienceId?'<div class="note">Puedes comparar experiencias distintas. Para integrarlas, selecciona dos revisiones de la misma experiencia.</div>':''}<div class="section-head" style="margin-top:37px"><div><div class="eyebrow">LECTURA TIPADA</div><h2>${d.conflicts.length?d.conflicts.length+' diferencias de criterio':'Sin conflicto tipado detectado'}</h2></div><p>La detección usa la misma pareja sujeto + predicado y valores distintos. La ausencia de conflicto detectado no garantiza compatibilidad.</p></div>${d.conflicts.map(c=>`<div class="conflict"><b>${esc(labels[c.type])}</b><p>A: ${esc(c.left)}<br>B: ${esc(c.right)}</p><small class="mono">${esc(c.subject)} / ${esc(c.predicate)}</small></div>`).join('')}${d.conflicts.some(x=>x.type!=='contradiction')?'<div class="note">La diferencia puede estar en las condiciones: conserva ambas lecciones con sus ámbitos. Un cambio de versión sugiere revalidar; no prueba por sí solo que la regla anterior fuera falsa.</div>':''}<div class="table-wrap"><table class="compare-table"><thead><tr><th>Dimensión</th><th>A / ${short(a.commitId)}</th><th>B / ${short(b.commitId)}</th></tr></thead><tbody>${d.changes.length?d.changes.map(x=>`<tr><td>${esc({title:'Título',goal:'Objetivo',scope:'Ámbito',constraints:'Restricciones',trace:'Trayectoria',outcome:'Resultado',lessons:'Lecciones',evidence:'Evidencia',actor:'Productor',validity:'Vigencia',classification:'Clasificación'}[x.field]||x.field)}</td><td><pre>${esc(typeof x.before==='string'?x.before:pretty(x.before))}</pre></td><td><pre>${esc(typeof x.after==='string'?x.after:pretty(x.after))}</pre></td></tr>`).join(''):'<tr><td colspan="3">No hay cambios en los campos comparados.</td></tr>'}</tbody></table></div><div class="quote-band"><div class="eyebrow">SEMÁNTICA DXP</div><blockquote>Integrar no significa decidir qué experiencia es verdadera. Significa conservar lo necesario para poder decidirlo.</blockquote></div></div>`;}
const modeLabels={none:'Sin memoria',raw:'Pool por proveedor',flat:'Resumen global',dxp:'DXP / ámbito'};
function labResults(){if(!report)return `<div class="panel" style="min-height:390px;display:flex;flex-direction:column;justify-content:center"><div class="eyebrow">EXPERIMENTO LISTO / SIN EJECUTAR</div><h2 style="font-size:35px;line-height:1.2;letter-spacing:-1px;font-weight:500">La misma lección.<br>Otro entorno.<br>¿Sigue funcionando?</h2><p>Ejecuta cuatro políticas sobre las mismas tareas sintéticas. Verás qué recuerdos se transfieren fuera de su ámbito y cuáles requieren abstenerse.</p><div class="note">Los consumidores son funciones deterministas, sin modelos, tokens ni coste de inferencia. La prueba enseña la mecánica; no valida H1–H6.</div></div>`;
 const rate=t=>(100*t.success/report.count).toFixed(1);
 return `<div class="scorecards">${Object.entries(report.totals).map(([k,t])=>`<article class="score ${k==='dxp'?'featured':''}"><span>${modeLabels[k]}</span><strong>${rate(t)}<span style="font-size:18px">%</span></strong><small>${t.success}/${report.count} tareas resueltas</small></article>`).join('')}</div><div class="bar-chart"><div class="eyebrow">ÉXITO / MISMAS TAREAS, DISTINTA POLÍTICA</div>${Object.entries(report.totals).map(([k,t])=>`<div class="barrow"><span>${modeLabels[k]}</span><div class="track"><div class="fill" style="width:${rate(t)}%"></div></div><b>${rate(t)}%</b></div>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>Política</th><th>Fallos</th><th>Abstenciones</th><th>Invocaciones simuladas</th></tr></thead><tbody>${Object.entries(report.totals).map(([k,t])=>`<tr><td>${modeLabels[k]}</td><td>${t.failures}</td><td>${t.abstentions}</td><td>${t.calls}</td></tr>`).join('')}</tbody></table></div><div class="note">Semilla ${report.seed} · ${report.count} tareas · v2 ${report.shift?'activa':'inactiva'} · registro no confiable ${report.poison?'activo':'inactivo'} · ámbito desconocido ${report.unknown?'activo':'inactivo'}. Las abstenciones cuentan como tareas no resueltas. Un 100% en este mundo construido no implica eficacia en agentes reales.</div><div class="actions"><button class="btn small dark" data-action="export-report">Exportar ejecución JSON ↗</button><button class="btn small ghost" data-action="export-csv">Descargar todas las tareas CSV</button></div><details><summary>Inspeccionar las primeras 12 tareas</summary><div class="table-wrap"><table><thead><tr><th>Tarea</th><th>Ámbito / límite</th><th>Sin memoria</th><th>Pool</th><th>Global</th><th>DXP</th></tr></thead><tbody>${report.rows.slice(0,12).map(r=>`<tr><td>${r.id}</td><td>${esc(r.task.provider)} / ${r.task.plan} / ${r.task.apiVersion}<br>cap = ${r.task.cap}</td>${Object.values(r.results).map(x=>`<td>${x.concurrency??'—'} workers<br>${x.abstain?'Abstención':x.success?'✓ Éxito':'× Fallo'}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>`;
}
function lab(){return `<div class="wrap">${heading('LABORATORIO / E0','Una experiencia útil tiene límites.','Microbenchmark determinista: capacidad de una API simulada, cambio de versión y un registro no confiable. Cada ejecución se puede reproducir y auditar.')}<div class="lab-layout"><aside class="lab-controls"><div class="eyebrow">CONFIGURAR EL ENTORNO</div><h3>Romper una buena regla.</h3><p>El mundo contiene cuatro ámbitos conocidos con límites 4, 2, 12 y 3. Una entrada externa aconseja 64 workers y está marcada como no confiable.</p><label>Semilla<input type="number" id="lab-seed" min="0" max="4294967295" value="${report?.seed??17}" aria-label="Semilla"></label><label>Tareas<input type="number" id="lab-count" min="1" max="10000" value="${report?.count??120}" aria-label="Cantidad de tareas"></label><label>Incluir cambio a v2<input id="lab-shift" type="checkbox" ${report?.shift===false?'':'checked'}></label><label>Incluir registro no confiable<input id="lab-poison" type="checkbox" ${report?.poison===false?'':'checked'}></label><label>Ámbito v3 desconocido (20%)<input id="lab-unknown" type="checkbox" ${report?.unknown?'checked':''}></label><button class="btn lime" data-action="run-lab">Ejecutar experimento ↗</button><p>Las reglas de consumo están visibles abajo. El filtro «trusted» viene dado por el simulador: no hay detección automática de ataques.</p></aside><section id="lab-results">${labResults()}</section></div><div class="section-head"><div><div class="eyebrow">POLÍTICAS TRANSPARENTES</div><h2>Qué hace cada consumidor.</h2></div><p>Baselines deliberadamente simples. Se comparan selectores de registros, no implementaciones completas de RAG, resúmenes de LLM ni productos comerciales.</p></div><div class="table-wrap"><table><thead><tr><th>Política</th><th>Regla exacta</th><th>Limitación</th></tr></thead><tbody><tr><td>Sin memoria</td><td>Concurrencia fija de 16.</td><td>No consulta el contrato del proveedor.</td></tr><tr><td>Pool por proveedor</td><td>Último registro que coincide con el proveedor.</td><td>Ignora plan, versión y confianza.</td></tr><tr><td>Resumen global</td><td>Último valor del pool completo.</td><td>Transforma una experiencia local en regla universal.</td></tr><tr><td>DXP / ámbito</td><td>Coincidencia exacta de proveedor + plan + versión y trusted=true.</td><td>Se abstiene si no hay coincidencia. La etiqueta de confianza es un oráculo.</td></tr></tbody></table></div><div class="split"><div class="panel"><h3>Un mundo totalmente inspeccionable</h3><p>Éxito significa concurrency ≤ cap. Las solicitudes son 20–99 por tarea. Invocaciones = ceil(requests/concurrency), multiplicadas por dos si hay rate limiting. Es una función de coste artificial; no mide latencia real.</p><details><summary>Ver el pool de experiencias sintéticas</summary><pre class="code">${esc(pretty(BENCH_MEMORY))}</pre></details></div><div class="panel"><h3>El siguiente experimento científico</h3><p>Separar tareas productoras y consumidoras, fijar presupuesto de contexto y comparar sin memoria, transcript, resumen y DXP. Introducir cambio de entorno, modelos distintos y evidencia adversaria. Medir éxito, transferencia negativa, coste total e incertidumbre.</p><a href="#protocol" class="btn small ghost">Explorar las seis hipótesis ↗</a></div></div></div>`;}
const hypotheses=[['H1','Transferencia útil','¿Experiencias estructuradas mejoran el éxito frente a no tener memoria y recuperar transcripts?','Refutar si no hay mejora frente al mejor baseline a presupuesto igual.'],['H2','Aprender del fallo','¿Añadir fallos documentados reduce la repetición de errores frente a conservar solo éxitos?','Refutar si la reducción no supera variación experimental o empeora éxito.'],['H3','Estructura y coste','¿Un objeto DXP conserva utilidad usando menos contexto que la trayectoria completa?','Refutar si pierde éxito o aumenta el coste total, incluida la captura.'],['H4','Ámbito y versiones','¿Historia y ámbito reducen transferencia negativa tras cambiar el entorno?','Refutar si un filtro simple por recencia obtiene el mismo resultado.'],['H5','Procedencia y confianza','¿El control de evidencia disminuye adopción de experiencias falsas?','Refutar si no supera retrieval simple o excluye demasiada experiencia útil.'],['H6','Interoperabilidad','¿Experiencias de un productor A ayudan a un consumidor B de otra familia?','Refutar si solo transfieren dentro de una familia o no superan experiencia propia.']];
function protocol(){return `<div class="wrap">${heading('CONTRATO / DXP 0.1','La experiencia como artefacto.','Una especificación candidata y un núcleo de referencia. El Atlas incluye una revisión documental real, además de ejemplos sintéticos. El contrato define qué intercambiar; los experimentos determinarán si merece convertirse en infraestructura.',`<a class="btn ghost" href="experience.schema.json" download>JSON Schema ↙</a><a class="btn dark" href="SPEC.md" download>Descargar especificación ↙</a>`)}<p class="big-statement">Conservar cómo cambió la comprensión que llevó a producir un resultado.</p><div class="flow"><div><span>01 / CAPTURAR</span><b>Hechos y decisiones declaradas</b><p>Objetivo, contexto, alternativas, acciones y resultados observables.</p></div><div><span>02 / VERSIONAR</span><b>Revisiones inmutables</b><p>Hash de contenido, padres y referencias a ramas. Evidencia en la revisión.</p></div><div><span>03 / CONTRASTAR</span><b>Ámbitos y desacuerdos</b><p>Diff por campos. Integración conservadora. Reversión documentada.</p></div><div><span>04 / TRANSFERIR</span><b>Datos con condiciones</b><p>JSON portable y paquete de contexto. Revisión y revalidación en destino.</p></div></div><div class="split"><div class="panel"><h3>Qué contiene una experiencia</h3><ul><li>Identidad de experiencia y productor declarado.</li><li>Objetivo, dominio, restricciones y ámbito.</li><li>Traza: observación, alternativas, decisión, razón resumida, acción, resultado e incertidumbre.</li><li>Lecciones tipadas, resultado y evidencia.</li><li>Vigencia, clasificación y marca de demostración.</li></ul><p>El commit añade fecha, padres, mensaje, operación y SHA-256. Una razón declarada es documentación observable, no acceso a razonamiento interno privado.</p></div><div class="panel"><h3>Qué garantías ofrece este núcleo</h3><ul><li>Integridad del contenido importado mediante hash.</li><li>Padres existentes, DAG ordenado y referencias válidas.</li><li>Actualización de rama ligada a su HEAD.</li><li>Merge con dos padres y ambas lecciones conservadas.</li><li>Revert como commit nuevo sobre un ancestro.</li></ul><p>El hash acredita igualdad de bytes canónicos; no identidad del autor, autenticidad de una observación ni verdad de una conclusión.</p></div></div><div class="section-head"><div><div class="eyebrow">OPERACIONES IMPLEMENTADAS</div><h2>Pequeñas primitivas. Una historia completa.</h2></div><p>El mismo núcleo se usa en la interfaz y en Node. No requiere un proveedor de modelos ni una base de datos externa.</p></div><div class="table-wrap"><table><thead><tr><th>Operación</th><th>Comportamiento real</th><th>Condición</th></tr></thead><tbody><tr><td class="mono">commit</td><td>Congela una experiencia y mueve la referencia de rama.</td><td>Validación estructural, padre HEAD y hash canónico.</td></tr><tr><td class="mono">branch</td><td>Crea una referencia sobre un commit existente.</td><td>No sobrescribe un nombre de rama.</td></tr><tr><td class="mono">diff</td><td>Compara dimensiones y claves sujeto/predicado/valor.</td><td>Sin inferencia de paráfrasis o causalidad.</td></tr><tr><td class="mono">merge</td><td>Une evidencia y lecciones; conserva padres y ámbitos.</td><td>Valores distintos bajo el mismo ámbito pasan a disputed; resultado incomplete.</td></tr><tr><td class="mono">revert</td><td>Copia un estado ancestral en una revisión nueva.</td><td>Conserva la historia, no deshace herramientas externas.</td></tr><tr><td class="mono">query / context</td><td>Búsqueda literal y paquete de lecciones por ámbito exacto.</td><td>El paquete excluye demos, cuarentena, intuiciones y disputas. Siempre exige revisión.</td></tr></tbody></table></div><details open><summary>DCE, DXP y los transportes</summary><p class="muted">DCE es una arquitectura ejecutable en TypeScript para convertir conocimiento de dominio en contexto específico de una tarea. El adaptador de esta edición captura una ejecución del motor, la registra en DXP y permite admitir una lección revisada en otro contexto DCE. <a href="#dce"><b>Ver explicación, repositorio y ejecuciones ↗</b></a>. REST, MCP y transferencia útil entre modelos siguen pendientes.</p><div class="note">Mapeo conceptual con W3C PROV: commit → Entity; ejecución → Activity; productor → Agent; padres → wasDerivedFrom. El objeto actual no se anuncia como implementación conforme a PROV-O.</div></details><details><summary>Gobernanza antes de compartir</summary><div class="split"><div><h3>El problema</h3><p class="muted">Un fallo individual puede propagarse como una regla compartida. La repetición entre agentes no crea evidencia independiente. Una firma tampoco convierte un claim en verdadero.</p></div><div><h3>La política candidata</h3><p class="muted">Redacción antes de captura, permisos por evidencia, revisión independiente, frescura, revocación e invalidación por dependencia. En este núcleo, «local» y «shareable» son etiquetas, no controles de acceso; no hay firmas ni detector general de inyección.</p></div></div></details><div class="section-head"><div><div class="eyebrow">PROGRAMA DE INVESTIGACIÓN</div><h2>Seis preguntas que pueden salir mal.</h2></div><p>Estas hipótesis sintetizan los cuatro documentos. Su numeración es propia de esta edición; ninguna está validada por el laboratorio sintético.</p></div><div class="research-grid">${hypotheses.map(h=>`<article><div class="eyebrow">${h[0]} / NO VALIDADA</div><h3>${h[1]}</h3><p>${h[2]}</p><small>${h[3]}</small></article>`).join('')}</div><div class="panel"><h3>Diseño mínimo de evaluación</h3><p>Productor A registra tareas de entrenamiento; consumidor B recibe tareas nuevas. Cuatro condiciones: sin memoria, transcript recuperado, resumen plano y DXP. Igualar presupuesto de contexto; separar semillas, tareas y fuentes; añadir cambio de contrato y repetir por familia de modelo. Añadir dos baselines cercanos: almacén plano con la misma procedencia y objetos equivalentes guardados en Git, sin semántica DXP. Comparar también fallos crudos frente a fallos anotados. Publicar resultados por tarea, intervalos de confianza y ablations de ámbito, historia y fallos.</p><p>Métricas: task success, repeated-error rate, harmful transfer, evidence-support rate, adopción adversaria, tool calls, tokens y coste total. Un resultado negativo debe publicarse como parte del conocimiento DXP.</p><a class="btn small ghost" href="RESEARCH.md" download>Descargar protocolo experimental ↙</a></div><div class="section-head"><div><div class="eyebrow">GUÍA DE USO</div><h2>Del atlas a tu propio agente.</h2></div></div><div class="split"><div class="panel"><h3>En el navegador</h3><p>Registra una experiencia propia. Escribe la observación y su evidencia, delimita el ámbito y añade una lección. Crea otra revisión si cambia tu conclusión. Exporta el repositorio e impórtalo en otro navegador.</p><button class="btn dark small" data-action="new">Registrar ahora ↗</button></div><div class="panel"><h3>En tu proyecto</h3><pre class="code">node cli.mjs init --store ./repository.json
node cli.mjs commit ./experience.json --branch lab/main
node cli.mjs log
node cli.mjs benchmark --seed 17</pre><p>El kit incluye CLI, módulo ESM, ejemplos, esquema, pruebas y documentación. El agente puede leer el JSON y producir una revisión; la automatización y la autorización corresponden al runtime que lo integre.</p><a class="btn ghost small" href="kit.zip" download>Descargar código y guía ↙</a></div></div></div>`;}
const primaries=[
 ['AXTP · Agent Experience Transfer Protocol','2026','https://axtp.dev/','Protocolo existente de intercambio de experiencias estructuradas: antecedente directo para DXP. Se consultaron su sitio y el README del repositorio.','La descripción de gobernanza no acredita su eficacia; no se auditó toda la implementación.'],
 ['GitOfThoughts','2026','https://arxiv.org/abs/2606.14470','Representa razonamiento y memoria en Git y evalúa su utilidad. El abstract informa límites de transferencia a problemas nuevos.','Se consultó el abstract primario; no se replicaron resultados ni se comprobó cada experimento.'],
 ['DCE · Domain Context Engine','v0.2.0','https://github.com/Milothik/domain-context-engine','Repositorio público de Milothik: arquitectura TypeScript que compila conocimiento de dominio en contexto para tareas. README, arquitectura, contratos y motor inspeccionados; integración offline ejecutada.','Es una referencia previa a 1.0. No demuestra eficacia de DXP ni generación de medios real.'],
 ['Anthropic / Scion','13.10.2026','https://www.anthropic.com/engineering/redesigning-source-control','El detonante arquitectónico: replantear source control ante producción agéntica masiva. Anthropic mantiene que Git encaja en la mayoría de repositorios.','No demuestra versionado ni transferencia de experiencias.'],
 ['Reflexion','2023','https://arxiv.org/abs/2303.11366','Feedback lingüístico y memoria episódica para aprender de intentos previos sin actualizar pesos.','Antecedente de reflexión; no valida DXP.'],
 ['ExpeL','2023–2024','https://andrewzh112.github.io/expel/','Extraer conocimiento de experiencias y reutilizarlo en tareas nuevas.','Aprendizaje experiencial preexistente; limita una reivindicación de novedad absoluta.'],
 ['AgentRR','2025','https://arxiv.org/abs/2505.17716','Record & replay, experiencia estructurada, restricciones y funciones de comprobación; propone repositorios de experiencias.','Antecedente directo. DXP debe justificar su semántica de versiones y ámbito.'],
 ['Agent Workflow Memory','2024','https://arxiv.org/abs/2409.07429','Inducción y reutilización de rutinas a partir de experiencias de navegación web.','Procedimientos reutilizables; sus resultados no son resultados del prototipo DXP.'],
 ['W3C / PROV-O','2013','https://www.w3.org/TR/prov-o/','Entity, Activity y Agent para modelar procedencia interoperable.','Procedencia no equivale a verdad. El mapeo de DXP es una propuesta.'],
 ['Memory Management / Xiong et al.','2025','https://arxiv.org/abs/2505.16067','Estudia propagación de errores y replay desalineado cuando experiencias antiguas guían tareas nuevas.','Justifica evaluar transferencia negativa; no prueba que el filtro DXP sea suficiente.']
];
function sources(){return `<div class="wrap">${heading('FUENTES / CRITERIO','Una idea con antecedentes.<br>Una síntesis con límites.','Las investigaciones de Meta, Grok, Gemini y GPT y la auditoría crítica posterior son el punto de partida. Esta edición separa esa síntesis secundaria de fuentes primarias consultadas y decisiones de diseño propias.')}<div class="panel"><div class="eyebrow">REVISIÓN DE CLAUDE / DECISIONES DE ESTA EDICIÓN</div><h3>Una crítica útil también debe contrastarse.</h3><p>Adoptamos la separación entre lo observado y lo declarado, la transferencia condicionada al consumidor y la comparación frente a memoria plana con procedencia equivalente y Git con los mismos objetos. La contribución candidata es la semántica de fusión y gobernanza de experiencias.</p><div class="table-wrap"><table><thead><tr><th>Conclusión del informe</th><th>Tratamiento comprobable</th></tr></thead><tbody><tr><td>No se encontró DCE público.</td><td>Corregida: repositorio v0.2.0 inspeccionado; código y motor enlazados en DCE.</td></tr><tr><td>Scion no sería un VCS de Anthropic.</td><td>Corregida con el artículo oficial del 13 de octubre. Hay proyectos homónimos.</td></tr><tr><td>Versionar memoria basta para ser novedoso.</td><td>El informe lo rechaza; compartimos ese criterio. La novedad no está establecida.</td></tr><tr><td>La transferencia puede empeorar resultados.</td><td>Motiva medir daño y abstención. Sus cifras pendientes no se presentan como resultados verificados.</td></tr><tr><td>H7: cobertura y condiciones de utilidad.</td><td>Se incorpora como pregunta experimental: ¿el ámbito predice cuándo una experiencia ayuda?</td></tr></tbody></table></div><div class="actions"><a class="btn small ghost" href="CLAUDE_REVIEW.md" download>Leer revisión completa ↙</a><a class="btn small dark" href="#dce">Consultar DCE y la evidencia ↗</a></div></div><div class="eyebrow">01 / LOS CINCO DOCUMENTOS APORTADOS</div><div class="sources-grid">${[['Meta IA DXP.txt','Resumen ejecutivo','Aporta el objeto de experiencia, el valor del fallo y un mapa de riesgos. Las cifras puntuales de seguridad se omiten en esta edición sin validación independiente.'],['Grok DXP.txt','Viabilidad y arquitectura','Ordena primitivas, hipótesis y métricas. Su afirmación de ausencia de equivalentes se trata como búsqueda parcial, no como prueba de originalidad.'],['Gemini DXP.txt','Formalización extensa','Explora mantenimiento de verdad, scope e invalidación. Contiene fórmulas con caracteres perdidos y garantías fuertes: se convierten en propuestas, no en garantías del software.'],['DXP versionado de experiencias agénticas.md','Investigación de Claude / revisión crítica','Introduce AXTP y GitOfThoughts, distingue observaciones de justificaciones y exige controles más fuertes. Sus conclusiones sobre Scion y la ausencia de DCE se corrigen con fuentes primarias. Las cifras marcadas verificar permanecen pendientes.'],['GPT DXP.txt','Síntesis crítica','Distingue DCE de DXP, plantea el DAG de revisiones y baselines. Los identificadores de citas del chat original no sustituyen enlaces verificables.']].map(x=>`<article class="source"><small>DOCUMENTO SECUNDARIO / APORTADO</small><h3>${x[0]}</h3><b class="small-text">${x[1]}</b><p>${x[2]}</p></article>`).join('')}</div><div class="section-head"><div><div class="eyebrow">02 / FUENTES PRIMARIAS</div><h2>Lo que fundamenta esta edición.</h2></div><p>Se verificó la existencia y el planteamiento de estas fuentes. No es una reproducción de sus experimentos ni una revisión exhaustiva de patentes.</p></div><div class="sources-grid">${primaries.map((x,i)=>`<article class="source"><div class="row"><small>P${i+1} / ${x[1]}</small>${badge('demo','Fuente primaria')}</div><h3>${x[0]}</h3><p>${x[3]}</p><p><b>Límite:</b> ${x[4]}</p><a href="${x[2]}" target="_blank" rel="noopener noreferrer">Abrir original ↗</a></article>`).join('')}</div><div class="section-head"><div><div class="eyebrow">03 / DECISIONES EDITORIALES</div><h2>Qué conservamos. Qué ponemos a prueba.</h2></div></div><div class="table-wrap"><table><thead><tr><th>Idea de las investigaciones</th><th>Tratamiento en Atlas</th><th>Estado</th></tr></thead><tbody><tr><td>Versionar experiencia y decisiones observables.</td><td>Contrato JSON, SHA-256, DAG, CLI y UI.</td><td>Implementado, alcance local.</td></tr><tr><td>Preservar fallos y divergencias.</td><td>Outcome failure, ramas, merge conservador y reversión.</td><td>Implementado.</td></tr><tr><td>Interpretar conflictos semánticos.</td><td>Comparación de claves y campos; conserva incertidumbre.</td><td>Aproximación tipada, sin comprensión automática.</td></tr><tr><td>Transferencia entre proveedores.</td><td>Formato neutral e importación verificable.</td><td>Portabilidad implementada; mejora de modelos sin evaluar.</td></tr><tr><td>Confianza, firmas, permisos y protección.</td><td>Etiquetas y revisión requerida; filtro oracular en benchmark.</td><td>Gobernanza de producción pendiente.</td></tr><tr><td>Git quedó obsoleto / DXP es totalmente nuevo.</td><td>Se conserva la pregunta sobre el objeto versionado; se reconocen antecedentes.</td><td>No se reivindica obsolescencia ni originalidad demostrada.</td></tr></tbody></table></div><div class="quote-band"><div class="eyebrow">CRITERIO DE INVESTIGACIÓN</div><blockquote>La literatura hace plausible la pregunta.<br>La respuesta tiene que venir de los experimentos.</blockquote></div><div class="actions"><a href="SOURCES.md" class="btn ghost" download>Descargar registro de fuentes ↙</a><a href="kit.zip" class="btn dark" download>Descargar toda la edición ↙</a></div></div>`;}
function render(){const route=location.hash.slice(1)||'start';const pages={start:()=>startPage({heading,esc,pretty,badge,step:guideStep,revision:guideRevision}),vision,atlas,compare,lab,protocol,sources,diary:()=>workPage({heading,esc,pretty,badge,taskIndex:workTask,tab:workTab}),dce:()=>dcePage({heading,esc,pretty,badge,caseIndex:dceCase})};$('#app').innerHTML=(pages[route]||pages.start)();document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.getAttribute('href')==='#'+route);if(a.classList.contains('active'))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(globalThis.__DXP_OFFLINE)document.querySelectorAll('a[href="kit.zip"]').forEach(a=>a.textContent='Exportar atlas HTML ↙');document.title='DXP · '+({start:'Una experiencia, paso a paso',vision:'Experience Atlas',atlas:'Atlas',compare:'Comparar',lab:'Laboratorio',protocol:'Protocolo',sources:'Fuentes',dce:'Domain Context Engine',diary:'Diario de construcción'}[route]||'Experience Atlas');}
const field=(name,label,value='',kind='input',extra='')=>`<label class="field ${extra}"><span>${label}</span>${kind==='textarea'?`<textarea name="${name}" required maxlength="12000">${esc(value)}</textarea>`:`<input name="${name}" value="${esc(value)}" required maxlength="500">`}</label>`;
const choose=(name,label,values,current)=>`<label class="field"><span>${label}</span><select name="${name}">${values.map(v=>`<option value="${esc(v[0])}" ${v[0]===current?'selected':''}>${esc(v[1])}</option>`).join('')}</select></label>`;
function dialog(title,content){$('#editor-content').innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="close" data-action="close" aria-label="Cerrar">×</button></div><div class="dialog-body">${content}</div>`;$('#editor').showModal();}
function editor(parent=null,forcedBranch=null){const c=parent?getCommit(repo,parent):null,e=c?.experience,l=e?.lessons[0],s=e?.trace.at(-1);let branchName=forcedBranch||Object.entries(repo.refs).find(([k,id])=>id===c?.commitId)?.[0]||'work/'+Date.now();const scope=e?.scope||{provider:'',environment:'',apiVersion:'',plan:''};
 dialog(c?'Registrar una nueva revisión':'Registrar una experiencia',`<form id="experience-form" data-parent="${c?.commitId||''}"><div class="note">Documenta lo observado y la razón resumida que quieras compartir. El registro no valida la conclusión. ${e?.demo?'Esta revisión conserva la marca DEMO de su historia.':''}</div><div class="form-grid">${field('title','Título',e?.title||'')}${field('branch','Rama',branchName)}${field('domain','Dominio',e?.domain||'')}${field('agentId','Agente / autor declarado',e?.actor.agentId||'')}${field('runtime','Runtime',e?.actor.runtime||'manual')}${choose('classification','Clasificación',[['local','Local'],['shareable','Compartible']],e?.classification||'local')}${field('goal','Objetivo',e?.goal||'','textarea','wide')}</div><h3>01 / Ámbito de aplicación</h3><div class="form-grid">${field('provider','Proveedor / fuente',scope.provider)}${field('plan','Plan / modalidad',scope.plan)}${field('apiVersion','Versión / corpus',scope.apiVersion)}${field('environment','Entorno',scope.environment)}</div><h3>02 / Un paso observable ${e?'adicional':''}</h3><div class="form-grid">${field('observation','Observación',s?.observation||'','textarea')}${field('alternatives','Alternativas — una por línea',s?.alternatives.join('\n')||'','textarea')}${field('selected','Decisión declarada',s?.selected||'')}${field('rationale','Razón resumida',s?.rationaleSummary||'')}${field('action','Acción realizada',s?.action||'')}${field('result','Resultado observable',s?.result||'')}${field('uncertainty','Incertidumbre / límites',s?.uncertainty||'Sin calibrar')}${choose('pivot','¿Cambio de estrategia?',[['false','No'],['true','Sí']],c?'true':'false')}</div><h3>03 / Evidencia declarada</h3><div class="form-grid">${field('evidenceLabel','Descripción de evidencia')}${field('evidenceContent','Contenido o referencia auditable','','textarea')}</div><h3>04 / Lección actual</h3><div class="form-grid">${field('claim','Conclusión con sus condiciones',l?.claim||'','textarea','wide')}${choose('type','Estado epistémico',[['hypothesis','Hipótesis'],['observation','Observación'],['intuition','Intuición'],['negative','Lección de fallo'],['disputed','En disputa']],l?.type||'hypothesis')}${field('subject','Sujeto de la lección',l?.subject||'')}${field('predicate','Propiedad / predicado',l?.predicate||'')}${field('value','Valor de esa propiedad',l?.value??'')}${choose('status','Resultado de la tarea',['success','failure','partial','incomplete'].map(x=>[x,labels[x]]),e?.outcome.status||'incomplete')}${choose('validity','Vigencia',['active','superseded','quarantined'].map(x=>[x,labels[x]]),e?.validity||'active')}${field('summary','Resumen del resultado',e?.outcome.summary||'','textarea','wide')}${field('message','Mensaje del commit','','input','wide')}</div><div class="error" id="form-error" role="alert"></div><div class="form-actions"><button type="button" class="btn ghost" data-action="close">Cancelar</button><button class="btn dark" type="submit">Crear commit ↗</button></div></form>`);
}
function operationDialog(action){
 if(action==='branch')return dialog('Abrir otra interpretación',`<form id="branch-form">${field('name','Nombre de la nueva rama','work/alternativa-'+Date.now())}<p class="muted small-text">La rama apunta a ${short(selected)}. Después podrás registrar su primera revisión.</p><div class="error" id="form-error" role="alert"></div><div class="form-actions"><button class="btn dark">Crear rama ↗</button></div></form>`);
 if(action==='merge'){const d=diff(getCommit(repo,compareA),getCommit(repo,compareB));return dialog('Integrar sin decidir por consenso',`<form id="merge-form"><div class="note">Se conservarán las dos lecciones, los ámbitos y los padres. ${d.conflicts.some(x=>x.type==='contradiction')?'Los valores incompatibles en el mismo ámbito pasarán a «en disputa».':'Los ámbitos distintos seguirán separados.'} El resultado se marcará incompleto: esta integración no ejecuta la tarea.</div>${field('name','Nueva rama de integración','integration/'+Date.now())}${field('note','Razón y límites de la integración','','textarea')}<div class="error" id="form-error" role="alert"></div><div class="form-actions"><button class="btn dark">Crear integración ↗</button></div></form>`);}
}
function showRevert(target){const candidates=Object.entries(repo.refs).filter(([k,id])=>history(repo,id).some(c=>c.commitId===target));if(!candidates.length)return notice('No hay una rama cuyo historial contenga este commit.');dialog('Recuperar un estado sin borrar historia',`<form id="revert-form" data-target="${target}">${choose('branch','Rama que recibirá la reversión',candidates.map(([k])=>[k,k]),candidates[0][0])}${field('note','Razón de la reversión','','textarea')}<div class="note">Un commit nuevo copiará el estado de ${short(target)}. Los commits y evidencias posteriores seguirán en el historial.</div><div class="error" id="form-error" role="alert"></div><div class="form-actions"><button class="btn dark">Registrar reversión ↗</button></div></form>`);}
async function action(name,el){
 if(name==='work-tab'){workTab=el.dataset.tab;render();return;}
 if(name==='work-task'){workTask=Number(el.dataset.task);render();return;}
 if(name==='guide-step'){const step=Number(el.dataset.step);if(Number.isInteger(step)&&step>=0&&step<=3){guideStep=step;render();$('#guide-step-title')?.focus();}return;}
 if(name==='guide-revision'){const record=guidedRecord(WORK_EVIDENCE.repository,el.dataset.id);guideRevision=record.selected.commitId;render();return;}
 if(name==='guide-atlas')return mutate(async()=>{await validateRepository(WORK_EVIDENCE.repository);const record=guidedRecord(WORK_EVIDENCE.repository,guideRevision),next=clone(repo),ids=new Set(next.commits.map(c=>c.commitId));for(const c of record.revisions)if(!ids.has(c.commitId)){next.commits.push(clone(c));ids.add(c.commitId);}const ref='guided/'+short(record.current.commitId);next.refs[ref]=record.current.commitId;await validateRepository(next);save(next);selected=record.selected.commitId;detailTab='experience';filters={text:'',domain:'',outcome:''};location.hash='atlas';});
 if(name==='work-export'){download('DXP-project-experiences.json',pretty(WORK_EVIDENCE.repository));return;}
 if(name==='work-import')return mutate(async()=>{await validateRepository(WORK_EVIDENCE.repository);const next=clone(repo),ids=new Set(next.commits.map(c=>c.commitId));for(const c of WORK_EVIDENCE.repository.commits)if(!ids.has(c.commitId)){next.commits.push(clone(c));ids.add(c.commitId);}for(const [ref,id] of Object.entries(WORK_EVIDENCE.repository.refs)){let name=ref;if(Object.hasOwn(next.refs,name)&&next.refs[name]!==id)name='import/'+short(id);next.refs[name]=id;}await validateRepository(next);save(next);selected=WORK_EVIDENCE.repository.commits[0].commitId;detailTab='experience';filters={text:'',domain:'',outcome:''};location.hash='atlas';notice('Diario de construcción añadido, con sus revisiones y evidencias.');});
 if(name==='dce-case'){dceCase=Number(el.dataset.case);render();return;}
 if(name==='dce-export'){download('DXP-DCE-executions.json',pretty(DCE_EVIDENCE.repository));return;}
 if(name==='dce-import')return mutate(async()=>{await validateRepository(DCE_EVIDENCE.repository);const next=clone(repo),ids=new Set(next.commits.map(c=>c.commitId));for(const c of DCE_EVIDENCE.repository.commits)if(!ids.has(c.commitId)){next.commits.push(clone(c));ids.add(c.commitId);}for(const [ref,id] of Object.entries(DCE_EVIDENCE.repository.refs)){let name=ref;if(Object.hasOwn(next.refs,name)&&next.refs[name]!==id)name='import/'+short(id);next.refs[name]=id;}await validateRepository(next);save(next);selected=DCE_EVIDENCE.repository.commits[0].commitId;detailTab='experience';filters={text:'',domain:'',outcome:''};location.hash='atlas';notice('Tres ejecuciones DCE añadidas. Sus datos de ejemplo y límites están en la evidencia.');});
 if(name==='close')return $('#editor').close();
 if(name==='new')return editor();
 if(name==='present'){presentation=!presentation;document.body.classList.toggle('presentation',presentation);if(presentation){location.hash='vision';window.scrollTo(0,0);}return;}
 if(name==='select'){selected=el.dataset.id;$('#detail').innerHTML=detail();$('#repo-results').innerHTML=commitList();return;}
 if(name==='tour'){selected=repo.commits[0].commitId;detailTab='trace';filters={text:'',domain:'',outcome:''};render();return;}
 if(name==='detail-tab'){detailTab=el.dataset.tab;$('#detail').innerHTML=detail();return;}
 if(name==='revise')return editor(selected);
 if(name==='branch'||name==='merge')return operationDialog(name);
 if(name==='revert')return showRevert(el.dataset.id);
 if(name==='compare-selected'){compareA=selected;compareB=repo.commits.find(c=>c.commitId!==selected&&c.experience.experienceId===getCommit(repo,selected).experience.experienceId)?.commitId||repo.commits.find(c=>c.commitId!==selected)?.commitId;location.hash='compare';return;}
 if(name==='swap'){[compareA,compareB]=[compareB,compareA];render();return;}
 if(name==='export-all'){download('DXP-repository.json',pretty(repo));notice('Repositorio exportado, incluidos registros locales.');return;}
 if(name==='export-one'){const subset={format:repo.format,version:repo.version,commits:history(repo,selected),refs:{'export/head':selected}};download('DXP-experience-'+short(selected)+'.json',pretty(subset));return;}
 if(name==='copy-json'){try{await navigator.clipboard.writeText(pretty(getCommit(repo,selected)));notice('Objeto copiado.');}catch{download('DXP-commit.json',pretty(getCommit(repo,selected)));}return;}
 if(name==='export-diff'){download('DXP-diff.json',pretty({a:compareA,b:compareB,...diff(getCommit(repo,compareA),getCommit(repo,compareB))}));return;}
 if(name==='import'){$('#import-file').value='';$('#import-file').click();return;}
 if(name==='run-lab'){try{report=runBenchmark({seed:Number($('#lab-seed').value),count:Number($('#lab-count').value),shift:$('#lab-shift').checked,poison:$('#lab-poison').checked,unknown:$('#lab-unknown').checked});$('#lab-results').innerHTML=labResults();notice('Experimento ejecutado. Datos completos disponibles para exportar.');}catch(e){notice(e.message);}return;}
 if(name==='export-report'){download('DXP-benchmark-seed-'+report.seed+'.json',pretty(report));return;}
 if(name==='export-csv'){const rows=[['task','provider','plan','version','cap','requests','policy','concurrency','success','abstain','calls'],...report.rows.flatMap(r=>Object.entries(r.results).map(([k,v])=>[r.id,r.task.provider,r.task.plan,r.task.apiVersion,r.task.cap,r.task.requests,k,v.concurrency??'',v.success,v.abstain,v.calls]))];download('DXP-benchmark.csv',rows.map(r=>r.join(',')).join('\r\n'),'text/csv');return;}
}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el&&!el.disabled){e.preventDefault();action(el.dataset.action,el).catch(err=>notice(err.message));}});
$('#new-global').addEventListener('click',()=>editor());
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&presentation){presentation=false;document.body.classList.remove('presentation');}});
document.addEventListener('input',e=>{if(e.target.id==='search'){filters.text=e.target.value;$('#repo-results').innerHTML=commitList();}});
document.addEventListener('change',e=>{if(e.target.id==='filter-domain'||e.target.id==='filter-outcome'){filters[e.target.id==='filter-domain'?'domain':'outcome']=e.target.value;$('#repo-results').innerHTML=commitList();}if(e.target.id==='compare-a'||e.target.id==='compare-b'){if(e.target.id==='compare-a')compareA=e.target.value;else compareB=e.target.value;render();}});
$('#editor').addEventListener('submit',e=>{e.preventDefault();mutate(async()=>{const form=e.target,fd=new FormData(form),v=k=>String(fd.get(k)||'').trim();const submit=form.querySelector('[type="submit"]')||form.querySelector('.form-actions button');submit.disabled=true;try{
 if(form.id==='experience-form'){
  const parent=form.dataset.parent?getCommit(repo,form.dataset.parent):null,existing=parent?.experience;const scope={provider:v('provider'),plan:v('plan'),apiVersion:v('apiVersion'),environment:v('environment')};const id='ev:'+crypto.randomUUID();const numValue=v('value');const value=numValue!==''&&Number.isFinite(Number(numValue))?Number(numValue):numValue;
  const step={step:(existing?.trace.length||0)+1,observation:v('observation'),alternatives:v('alternatives').split('\n').map(x=>x.trim()).filter(Boolean),selected:v('selected'),rationaleSummary:v('rationale'),action:v('action'),result:v('result'),uncertainty:v('uncertainty'),pivot:v('pivot')==='true',evidenceRefs:[id]};
  const x={schemaVersion:'0.1',experienceId:existing?.experienceId||'exp:'+crypto.randomUUID(),title:v('title'),domain:v('domain'),goal:v('goal'),actor:{agentId:v('agentId'),runtime:v('runtime'),model:'not-declared',identityStatus:'declared'},scope,constraints:existing?.constraints||['Validar aplicabilidad antes de reutilizar.'],trace:[...(existing?clone(existing.trace):[]),step],outcome:{status:v('status'),summary:v('summary')},lessons:[{subject:v('subject'),predicate:v('predicate'),value,claim:v('claim'),type:v('type'),scope,evidenceRefs:[id]}],evidence:[...(existing?clone(existing.evidence):[]),{id,label:v('evidenceLabel'),content:v('evidenceContent'),kind:'declared'}],validity:v('validity'),classification:v('classification'),demo:existing?.demo||false};
  const r=await commit(repo,x,{parents:parent?[parent.commitId]:[],branch:v('branch'),message:v('message')});save(r.repo);selected=r.commit.commitId;
 } else if(form.id==='branch-form'){save(branch(repo,selected,v('name')));$('#editor').close();render();notice('Rama creada. Registra su primera revisión.');editor(selected,v('name'));return;
 } else if(form.id==='merge-form'){const r=await merge(repo,compareA,compareB,v('name'),v('note'));save(r.repo);selected=r.commit.commitId;
 } else if(form.id==='revert-form'){const r=await revert(repo,v('branch'),form.dataset.target,v('note'));save(r.repo);selected=r.commit.commitId;}
 $('#editor').close();location.hash='atlas';render();notice('Historia guardada. '+short(selected));
 }catch(err){$('#form-error').textContent=err.message;}finally{submit.disabled=false;}});});
$('#import-file').addEventListener('change',()=>mutate(async()=>{const f=$('#import-file').files[0];if(!f)return;if(f.size>5*1024*1024)throw Error('El archivo supera 5 MiB.');const incoming=JSON.parse(await f.text());await validateRepository(incoming);const next=clone(repo),seen=new Set(next.commits.map(c=>c.commitId));for(const c of incoming.commits){if(!seen.has(c.commitId)){next.commits.push(c);seen.add(c.commitId);}}for(const [name,id] of Object.entries(incoming.refs)){let key=name;if(Object.hasOwn(next.refs,key)&&next.refs[key]!==id){key='import/'+short(id);let i=1;while(Object.hasOwn(next.refs,key)&&next.refs[key]!==id)key='import/'+short(id)+'-'+i++;}next.refs[key]=id;}await validateRepository(next);save(next);selected=incoming.commits.at(-1)?.commitId||selected;location.hash='atlas';render();notice('Importación verificada: '+incoming.commits.length+' commits; historia conservada.');}));
const exit=document.createElement('button');exit.className='btn small presentation-exit';exit.dataset.action='present';exit.textContent='Salir de presentación · Esc';document.body.append(exit);
